{
  "applicability_terms": ["induction motor", "rated voltage", "PI"],
  "inputs": [
    {"name": "rated_voltage", "kind": "voltage", "cues": []},
    {"name": "measured_insulation", "kind": "resistance", "cues": []},
    {"name": "winding_temperature", "kind": "temperature", "cues": []},
    {"name": "polarization_index", "kind": "cued", "cues": ["PI", "polarization index"]}
  ],
  "out_of_scope_terms": ["transformers", "cables", "generators", "motors rated above 11 kV"],
  "out_of_scope_conditions": ["winding_temperature < 10 or winding_temperature > 75"],
  "missing_input_outcome": "INSUFFICIENT_INPUT",
  "derived": [
    {"name": "corrected_resistance", "expr": "measured_insulation * 2^(winding_temperature - 40) / 10"}
  ],
  "rules": [
    {
      "when": "winding_temperature < 10 or winding_temperature > 75",
      "outcome": "INVALID_TEST"
    },
    {
      "when": "corrected_resistance < 0.5 * minimum",
      "outcome": "REJECT"
    },
    {
      "when": "corrected_resistance < minimum",
      "outcome": "DRY_OUT"
    },
    {
      "when": "corrected_resistance >= minimum and PI < 1.5",
      "outcome": "RETEST_30D"
    },
    {
      "when": "PI >= 1.5 and PI < 2.0",
      "outcome": "PASS"
    }
  ],
  "default_outcome": "PASS"
}

